package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock is the production Clock.
var RealClock Clock = realClock{}

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be constructed with NewLimiter; the zero value is invalid.
type Limiter struct {
	mu        sync.Mutex
	clock     Clock
	rate      float64 // tokens per second
	burst     float64 // bucket capacity
	tokens    float64
	lastRefill time.Time
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// NewLimiter creates a Limiter that admits events at rate tokens per second,
// with a maximum burst size. The bucket starts full.
func NewLimiter(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	return &Limiter{
		clock:      clock,
		rate:       rate,
		burst:      float64(burst),
		tokens:     float64(burst),
		lastRefill: clock.Now(),
	}, nil
}

// refill advances the bucket to time now, accumulating tokens.
// Caller must hold l.mu.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.lastRefill)
	if elapsed <= 0 {
		return
	}
	l.tokens += elapsed.Seconds() * l.rate
	if l.tokens > l.burst {
		l.tokens = l.burst
	}
	l.lastRefill = now
}

// AllowN reports whether n tokens may be consumed at time time.Now().
// If the bucket has insufficient tokens, nothing is consumed.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.clock.Now()
	l.refill(now)
	need := float64(n)
	if l.tokens < need {
		return false
	}
	l.tokens -= need
	return true
}

// Allow reports whether a single token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// Tokens returns the current number of available tokens (refilled to now).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(l.clock.Now())
	return l.tokens
}
