// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be constructed with NewLimiter; the zero value is not usable.
type Limiter struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// ErrInvalidConfig is returned by NewLimiter for invalid parameters.
var ErrInvalidConfig = errors.New("ratelimit: capacity and rate must be > 0")

// NewLimiter creates a Limiter with the given burst capacity (tokens),
// refill rate (tokens per second), and initial token count. If clock is nil,
// the real clock is used. initialTokens is clamped to [0, capacity].
func NewLimiter(capacity, rate, initialTokens float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 || capacity != capacity || rate != rate ||
		capacity > 1e308 || rate > 1e308 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = realClock{}
	}
	tokens := initialTokens
	if tokens < 0 || tokens != tokens {
		tokens = 0
	}
	if tokens > capacity {
		tokens = capacity
	}
	return &Limiter{
		capacity: capacity,
		rate:     rate,
		tokens:   tokens,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// refill advances the bucket state to time now.
// Caller must hold l.mu.
func (l *Limiter) refill(now time.Time) {
	if elapsed := now.Sub(l.last); elapsed > 0 {
		l.tokens += elapsed.Seconds() * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
	}
	l.last = now
}

// AllowN reports whether n tokens may be consumed at time clock.Now(),
// consuming them if so.
func (l *Limiter) AllowN(n float64) bool {
	return l.allowAt(l.clock.Now(), n)
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

func (l *Limiter) allowAt(now time.Time, n float64) bool {
	if n < 0 || n != n {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	if l.tokens < n {
		return false
	}
	l.tokens -= n
	return true
}

// Tokens returns the number of tokens currently available, after refilling
// up to the current time.
func (l *Limiter) Tokens() float64 {
	now := l.clock.Now()
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	return l.tokens
}
