// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// realClock uses the standard library.
type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A Limiter must be constructed with NewLimiter; the zero value is not usable.
type Limiter struct {
	mu        sync.Mutex
	tokens    float64
	max       float64
	refill    float64 // tokens per second
	last      time.Time
	clock     Clock
	nowFn     func() time.Time // set only when clock is nil
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock and nowFn cannot both be nil")
)

// Option configures a Limiter.
type Option func(*options)

type options struct {
	clock Clock
	nowFn func() time.Time
}

// WithClock injects a custom Clock implementation.
func WithClock(c Clock) Option {
	return func(o *options) { o.clock = c }
}

// WithNowFunc injects a plain time function (mutually exclusive with WithClock).
func WithNowFunc(f func() time.Time) Option {
	return func(o *options) { o.nowFn = f }
}

// NewLimiter creates a Limiter that refills at rate tokens per second,
// holding at most burst tokens. The bucket starts full.
func NewLimiter(rate float64, burst int, opts ...Option) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	var o options
	for _, opt := range opts {
		opt(&o)
	}
	l := &Limiter{
		tokens: float64(burst),
		max:    float64(burst),
		refill: rate,
	}
	switch {
	case o.clock != nil && o.nowFn != nil:
		return nil, errors.New("ratelimit: WithClock and WithNowFunc are mutually exclusive")
	case o.clock != nil:
		l.clock = o.clock
	case o.nowFn != nil:
		l.nowFn = o.nowFn
	default:
		return nil, ErrNilClock
	}
	l.last = l.now()
	return l, nil
}

func (l *Limiter) now() time.Time {
	if l.clock != nil {
		return l.clock.Now()
	}
	return l.nowFn()
}

// refill advances the bucket to time t, adding accrued tokens.
func (l *Limiter) refill(t time.Time) {
	elapsed := t.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens = min(l.max, l.tokens+elapsed*l.refill)
		l.last = t
	}
}

// AllowN reports whether n tokens may be consumed at time now.
func (l *Limiter) AllowN(n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	l.refill(now)
	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now. n must be non-negative.
func (l *Limiter) RetryAfter(n int) time.Duration {
	if n < 0 {
		return -1
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	now := l.now()
	l.refill(now)
	deficit := float64(n) - l.tokens
	if deficit <= 0 {
		return 0
	}
	return time.Duration(deficit / l.refill * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
